# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ORUÇ İBADETİNİN FARZ OLMA (SORUMLULUK) ŞARTLARI VE RÜKÜNLERİ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Oruçla Yükümlü Olma Şartları</text>\n  <text x="182" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Müslüman Olmak</text>\n  <text x="182" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Akıllı Olmak (Temyiz gücüne sahip olmak)</text>\n  <text x="182" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Ergenlik Çağına Ulaşmış Olmak (Bülûğ)</text>\n  <text x="182" y="184" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Oruç Tutmasına Engel Durumu Bulunmamak</text>\n  <text x="182" y="210" text-anchor="middle" font-size="11" fill="#475569">(Sağlıklı olmak ve mukim yani yerleşik olmak)</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Orucun Geçerlilik Unsurları ve Kolaylıklar</text>\n  <text x="517" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">1. Niyet Etmek (Kalben veya dille)</text>\n  <text x="517" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">2. İmsak Vaktinden İftara Kadar Sakınmak</text>\n  <text x="517" y="154" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Dinen İzin Verilen Ruhsat Sahipleri:</text>\n  <text x="517" y="176" text-anchor="middle" font-size="11" fill="#334155">• Hastalar ve Yolcular (Seferîler) ➔ Sonra kazâ eder</text>\n  <text x="517" y="196" text-anchor="middle" font-size="11" fill="#334155">• Hamile / Emziren Kadınlar ➔ Sonra kazâ eder</text>\n  <text x="517" y="216" text-anchor="middle" font-size="11" fill="#334155">• İyileşemeyecek Yaşlı/Hastalar ➔ Fidye verir</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ORUCU BOZAN VE BOZMAYAN DURUMLAR İLE KAZÂ - KEFARET</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Orucu Bozan Durumlar</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" fill="#7f1d1d">• Bilerek bir şey yemek ve içmek</text>\n  <text x="125" y="120" text-anchor="middle" font-size="11" fill="#7f1d1d">• Besleyici serum / vitamin almak</text>\n  <text x="125" y="142" text-anchor="middle" font-size="11" fill="#7f1d1d">• Ağızdan ilaç veya şurup içmek</text>\n  <text x="125" y="164" text-anchor="middle" font-size="11" fill="#7f1d1d">• Abdestte hata ile su yutmak</text>\n  <text x="125" y="186" text-anchor="middle" font-size="11" fill="#7f1d1d">• İmsak girdikten sonra yemek</text>\n  <text x="125" y="208" text-anchor="middle" font-size="11" fill="#7f1d1d">• Kendi isteğiyle ağız dolusu kusmak</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Orucu Bozmayan Durumlar</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" fill="#14532d">• Unutarak yemek ve içmek</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" fill="#14532d">• Yutmadan ağzı çalkalamak / duş</text>\n  <text x="350" y="142" text-anchor="middle" font-size="11" fill="#14532d">• Diş fırçalamak (su yutmadan)</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11" fill="#14532d">• Göz veya kulak damlası, kan vermek</text>\n  <text x="350" y="186" text-anchor="middle" font-size="11" fill="#14532d">• Besleyici olmayan tedavi iğnesi</text>\n  <text x="350" y="208" text-anchor="middle" font-size="11" fill="#14532d">• Kendi kendine (istemsiz) kusmak</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Kazâ, Kefaret ve Fidye</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">• Kazâ Orucu (1\'e 1):</text>\n  <text x="575" y="114" text-anchor="middle" font-size="10.5" fill="#475569">Mazeretle veya hata ile bozulan oruç</text>\n  <text x="575" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">• Kefaret Orucu (60 + 1 gün):</text>\n  <text x="575" y="154" text-anchor="middle" font-size="10.5" fill="#475569">Ramazan orucunu mazeretsiz bilerek bozma</text>\n  <text x="575" y="178" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">• Fidye (1 günlük yemek bedeli):</text>\n  <text x="575" y="194" text-anchor="middle" font-size="10.5" fill="#475569">Oruç tutamayacak yaşlı ve kronik hastalar</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAM\'DA ORUÇ ÇEŞİTLERİ VE TOPLUMSAL KAZANIMLARI</text>\n  <rect x="20" y="50" width="152" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="96" y="75" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Farz Oruç</text>\n  <text x="96" y="104" text-anchor="middle" font-size="11" fill="#1e3a8a">Ramazan ayında</text>\n  <text x="96" y="122" text-anchor="middle" font-size="11" fill="#1e3a8a">tutulan oruç ile</text>\n  <text x="96" y="140" text-anchor="middle" font-size="11" fill="#1e3a8a">tutulamayan</text>\n  <text x="96" y="158" text-anchor="middle" font-size="11" fill="#1e3a8a">Ramazan oruçlarının</text>\n  <text x="96" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">kazâsıdır.</text>\n\n  <rect x="188" y="50" width="152" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="264" y="75" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Vacip Oruç</text>\n  <text x="264" y="104" text-anchor="middle" font-size="11" fill="#14532d">Adak (nezir)</text>\n  <text x="264" y="122" text-anchor="middle" font-size="11" fill="#14532d">orucu ile başlanıp</text>\n  <text x="264" y="140" text-anchor="middle" font-size="11" fill="#14532d">bozulan nafile</text>\n  <text x="264" y="158" text-anchor="middle" font-size="11" fill="#14532d">oruçların</text>\n  <text x="264" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">kazâsıdır.</text>\n\n  <rect x="356" y="50" width="152" height="185" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="432" y="75" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">3. Sünnet / Nafile</text>\n  <text x="432" y="104" text-anchor="middle" font-size="11" fill="#581c87">Muharrem (Aşure),</text>\n  <text x="432" y="122" text-anchor="middle" font-size="11" fill="#581c87">Şevval (6 gün),</text>\n  <text x="432" y="140" text-anchor="middle" font-size="11" fill="#581c87">Arefe, Pazartesi-</text>\n  <text x="432" y="158" text-anchor="middle" font-size="11" fill="#581c87">Perşembe ve</text>\n  <text x="432" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Eyyâm-ı Bîz.</text>\n\n  <rect x="524" y="50" width="156" height="185" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="602" y="75" text-anchor="middle" font-size="12" font-weight="bold" fill="#c2410c">4. Birey ve Toplum</text>\n  <text x="602" y="104" text-anchor="middle" font-size="11" fill="#7c2d12">Sabır ve iradeyi</text>\n  <text x="602" y="122" text-anchor="middle" font-size="11" fill="#7c2d12">güçlendirir; empati,</text>\n  <text x="602" y="140" text-anchor="middle" font-size="11" fill="#7c2d12">merhamet, şükür ve</text>\n  <text x="602" y="158" text-anchor="middle" font-size="11" fill="#7c2d12">yardımlaşma bilincini</text>\n  <text x="602" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#c2410c">geliştirir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
